package io.zingg.duckdb.api;
import java.util.List;
public interface Frame {
  JobId owner(); List<String> columns(); List<Column> schema(); List<Row> collect(); List<Row> collect(CancellationToken cancellation);
  String explain();
  Frame select(String... columns); Frame selectExpr(String... expressions); Frame selectZeroColumns(); Frame filter(Expression expression); Frame filterInCond(Frame values,String leftColumn,String rightColumn); Frame explode(String listColumn,String outputColumn); Frame sort(String... expressions); Frame limit(long rows); SplitResult partitionByPredicate(Expression expression); SplitResult split(Expression expression); Frame split(String column,String pattern,String resultColumn); Frame aggregate(String[] groups,String... aggregates); Frame repartition(int partitions); Frame coalesce(int partitions); <T> Frame withColumn(String name,T value); Frame drop(String... columns); Frame rename(String from,String to); Frame join(Frame right,String condition); Frame join(Frame right,String condition,String joinType); Frame joinUsing(Frame right,String joinType,String... columns); Frame joinProjected(Frame right,String condition,String rightPrefix); Frame union(Frame other,boolean byName,boolean allowMissing); Frame except(Frame other); Frame intersect(Frame other); Frame distinct(); Frame dropDuplicates(String... columns); Frame sample(boolean withReplacement,double fraction); Frame cache(); long count(); long count(CancellationToken cancellation); void writeCsv(java.nio.file.Path output,boolean header); void writeParquet(java.nio.file.Path output); void writeJson(java.nio.file.Path output); void writeArrow(java.nio.file.Path output);
}
